3	#include <algorithm>
4	
5	namespace amr_dispatcher_core::chassis {
6	
7	LinkQualityMonitor::LinkQualityMonitor(LinkQualityConfig config)
8	    : config_(config), window_(config.window_size, Sample{}) {}
9	
10	void LinkQualityMonitor::RecordSuccess(const double latency_ms) {
11	  std::lock_guard<std::mutex> lock(mutex_);
12	  window_[head_] = Sample{true, latency_ms};
13	  head_ = (head_ + 1) % config_.window_size;
14	  if (window_filled_ < config_.window_size) {
15	    ++window_filled_;
16	  }
17	  ++total_success_;
18	  ++consecutive_success_;
19	  latency_sum_ms_ += latency_ms;
20	  latency_max_ms_ = std::max(latency_max_ms_, latency_ms);
21	  last_seen_ = std::chrono::steady_clock::now();
22	  if (consecutive_success_ >= config_.success_threshold &&
23	      tier_ != LinkHealthTier::kHealthy) {
24	    ++pending_recovery_signal_;
25	  }
26	  RecomputeLocked();
27	}
28	
29	void LinkQualityMonitor::RecordLoss() {
30	  std::lock_guard<std::mutex> lock(mutex_);
31	  window_[head_] = Sample{false, 0.0};
32	  head_ = (head_ + 1) % config_.window_size;
33	  if (window_filled_ < config_.window_size) {
34	    ++window_filled_;
35	  }
36	  ++total_lost_;
37	  consecutive_success_ = 0;
38	  last_seen_ = std::chrono::steady_clock::now();
39	  RecomputeLocked();
40	}
41	
42	void LinkQualityMonitor::RecordCrcError() {
43	  std::lock_guard<std::mutex> lock(mutex_);
44	  window_[head_] = Sample{false, 0.0};
45	  head_ = (head_ + 1) % config_.window_size;
46	  if (window_filled_ < config_.window_size) {
47	    ++window_filled_;
48	  }
49	  ++total_crc_error_;
50	  ++total_lost_;
51	  consecutive_success_ = 0;
52	  RecomputeLocked();
53	}
54	
55	void LinkQualityMonitor::RecomputeLocked() {
56	  cached_snapshot_.frames_total = total_success_ + total_lost_;
57	  cached_snapshot_.frames_success = total_success_;
58	  cached_snapshot_.frames_lost = total_lost_;
59	  cached_snapshot_.frames_crc_error = total_crc_error_;
60	  if (cached_snapshot_.frames_total == 0) {
61	    cached_snapshot_.loss_rate = 0.0;
62	    cached_snapshot_.average_latency_ms = 0.0;
63	    cached_snapshot_.max_latency_ms = 0.0;
64	    tier_ = LinkHealthTier::kUnknown;
65	    cached_snapshot_.tier = tier_;
66	    return;
67	  }
68	  cached_snapshot_.loss_rate =
69	      static_cast<double>(cached_snapshot_.frames_lost) / static_cast<double>(cached_snapshot_.frames_total);
70	  cached_snapshot_.average_latency_ms =
71	      total_success_ > 0 ? latency_sum_ms_ / static_cast<double>(total_success_) : 0.0;
72	  cached_snapshot_.max_latency_ms = latency_max_ms_;
73	  cached_snapshot_.last_seen = last_seen_;
74	
75	  // 优先级：critical > degraded > healthy > unknown
76	  if (cached_snapshot_.loss_rate >= config_.degraded_loss_rate * 2.0) {
77	    tier_ = LinkHealthTier::kCritical;
78	  } else if (cached_snapshot_.loss_rate >= config_.degraded_loss_rate) {
79	    tier_ = LinkHealthTier::kDegraded;
80	  } else if (cached_snapshot_.loss_rate <= config_.healthy_loss_rate &&
81	             consecutive_success_ >= config_.success_threshold) {
82	    tier_ = LinkHealthTier::kHealthy;
83	  } else if (tier_ == LinkHealthTier::kUnknown) {
84	    tier_ = LinkHealthTier::kDegraded;
85	  }
86	  cached_snapshot_.tier = tier_;
87	}
88	
89	LinkQualitySnapshot LinkQualityMonitor::Snapshot() const {
90	  std::lock_guard<std::mutex> lock(mutex_);
91	  return cached_snapshot_;
92	}
93	
94	LinkHealthTier LinkQualityMonitor::CurrentTier() const {
95	  std::lock_guard<std::mutex> lock(mutex_);
96	  return tier_;
97	}
98	
99	bool LinkQualityMonitor::IsHealthy() const {
100	  std::lock_guard<std::mutex> lock(mutex_);
101	  return tier_ == LinkHealthTier::kHealthy;
102	}
103	
104	bool LinkQualityMonitor::IsCritical() const {
105	  std::lock_guard<std::mutex> lock(mutex_);
106	  return tier_ == LinkHealthTier::kCritical;
107	}
108	
109	bool LinkQualityMonitor::ConsumeRecoverySignal() {
110	  std::lock_guard<std::mutex> lock(mutex_);
111	  if (pending_recovery_signal_ == 0) {
112	    return false;
113	  }
114	  --pending_recovery_signal_;
115	  return true;
116	}
117	
118	void LinkQualityMonitor::Reset() {
119	  std::lock_guard<std::mutex> lock(mutex_);
120	  std::fill(window_.begin(), window_.end(), Sample{});
121	  head_ = 0;
122	  window_filled_ = 0;
123	  total_success_ = 0;
124	  total_lost_ = 0;
125	  total_crc_error_ = 0;
126	  consecutive_success_ = 0;
127	  pending_recovery_signal_ = 0;
128	  latency_sum_ms_ = 0.0;
129	  latency_max_ms_ = 0.0;
130	  cached_snapshot_ = LinkQualitySnapshot{};
131	  tier_ = LinkHealthTier::kUnknown;
132	}
133	
134	}  // namespace amr_dispatcher_core::chassis
