90	    const std::string& resource_id,
91	    std::chrono::steady_clock::time_point start,
92	    std::chrono::steady_clock::time_point end,
93	    std::string* message) {
94	  if (start >= end) {
95	    if (message) *message = "invalid time interval: start >= end";
96	    return false;
97	  }
98	
99	  // 1. 检查是否存在永久排他锁（人工封路等）
100	  if (Locked(resource_id) && Owner(resource_id) != mission_id) {
101	    if (message) *message = "resource statically locked by: " + *Owner(resource_id);
102	    return false;
103	  }
104	
105	  // 2. 检查该资源在目标时间区间内是否与其他任务的预约时段重叠
106	  TimeInterval candidate_interval{start, end};
107	  auto& reservations = time_space_reservations_[resource_id];
108	  for (const auto& res : reservations) {
109	    if (res.mission_id != mission_id && res.interval.OverlapsWith(candidate_interval)) {
110	      if (message) {
111	        *message = "time-space contention on " + resource_id + " with " + res.mission_id;
112	      }
113	      return false;
114	    }
115	  }
116	
117	  // 3. 无时空冲突，落入预约表
118	  reservations.push_back(TimeSpaceReservation{mission_id, resource_id, candidate_interval});
119	  if (message) *message = "time-space reservation confirmed";
120	  return true;
121	}
