123	ResourceTable::ReleaseResult ResourceTable::Release(const std::string& mission_id) {
124	  ReleaseResult result;
125	  for (auto lock = locks_.begin(); lock != locks_.end();) {
126	    if (lock->second == mission_id) {
127	      lock = locks_.erase(lock);
128	      result.released = true;
129	    } else {
130	      ++lock;
131	    }
132	  }
133	
134	  // 清空该任务的所有时空预约
135	  for (auto& [res_id, list] : time_space_reservations_) {
136	    auto before_size = list.size();
137	    list.erase(std::remove_if(list.begin(), list.end(),
138	                              [&mission_id](const TimeSpaceReservation& r) {
139	                                return r.mission_id == mission_id;
140	                              }),
141	               list.end());
142	    if (list.size() < before_size) {
143	      result.released = true;
144	    }
145	  }
146	
147	  result.message =
148	      result.released ? "released resources of " + mission_id : "no resources held by " + mission_id;
149	  return result;
