155	  const auto existing = locks_.find(resource_id);
156	  if (existing != locks_.end()) {
157	    if (message != nullptr) {
158	      *message = "resource already held: " + resource_id + " by " + existing->second;
159	    }
160	    return false;
161	  }
162	  locks_[resource_id] = owner;
163	  if (message != nullptr) {
164	    *message = "blocked " + resource_id;
165	  }
166	  return true;
167	}
