170	  const auto existing = locks_.find(resource_id);
171	  if (existing == locks_.end()) {
172	    if (message != nullptr) {
173	      *message = "resource not locked: " + resource_id;
174	    }
175	    return false;
176	  }
177	  if (!IsTrafficBlockOwner(existing->second)) {
178	    if (message != nullptr) {
179	      *message = "cannot unblock resource held by mission: " + existing->second;
180	    }
181	    return false;
182	  }
183	  locks_.erase(existing);
184	  if (message != nullptr) {
185	    *message = "unblocked " + resource_id;
186	  }
187	  return true;
188	}
