#include <unordered_map>
#include <unordered_set>
#include <vector>

#include "amr_dispatcher_core/dispatcher/mission_state.hpp"

namespace amr_dispatcher_core::dispatcher {

// 死锁检测配置
struct DeadlockDetectorConfig {
  std::size_t max_active_missions = 16;        // 同时活跃 mission 上限
  std::chrono::milliseconds active_idle_threshold{std::chrono::seconds(10)};
  std::chrono::milliseconds reservation_hold_threshold{std::chrono::seconds(30)};
};

// 资源申请与等待状态模型 (Wait-For Graph 模型)
struct ResourceAllocationModel {
  // mission_id -> 任务当前正在等待申请的资源 ID 列表 (例如等待 route_edge:B__C)
  std::unordered_map<std::string, std::vector<std::string>> waiting_for;
  // resource_id -> 当前持有该资源的 mission_id
  std::unordered_map<std::string, std::string> held_by;
};

// 死锁检测输入快照：调用方从外部聚合 mission 状态 + traffic_reservation 状态。
struct DeadlockSnapshot {
  std::vector<Mission> active_missions;          // 当前 ACTIVE 的任务
  std::unordered_map<std::string, std::chrono::steady_clock::time_point> last_progress;
  std::unordered_map<std::string, std::chrono::steady_clock::time_point> reservation_acquired_at;
  std::unordered_set<std::string> reserved_resource_ids;

  // 严密的资源依赖分配关系（支持 0 毫秒图论环检测）
  ResourceAllocationModel allocation_graph;
};

// 检测结论：单次 Detect 返回的所有嫌疑。
enum class DeadlockKind {
  kIdleActive,            // ACTIVE 任务在 idle_threshold 内无 progress
  kLongReservationHold,   // 持有资源超过阈值
  kMutualBlock,           // 依赖环死锁 (Wait-For Graph 存在环)
};

struct DeadlockFinding {
  std::vector<std::string> mission_ids;  // 涉及的 mission_id
  DeadlockKind kind = DeadlockKind::kIdleActive;
  std::string description;
  std::vector<std::string> cycle_path;   // 具体的成环路径：任务与资源交替并闭合回起始
                                          // 任务，例如 [m1, route_edge:A__B, m2,
                                          // route_node:C, m1]（偶数位任务、奇数位资源）
};

/**
 * @brief 工业级死锁检测器
 * 同时具备：
 * 1. 纯图论的 Wait-For-Graph (WFG) DFS 有向图环检测（0 毫秒确定性识别循环互斥争抢）；
 * 2. 启发式超时与长时间持锁兜底监控。
 */
class DeadlockDetector {
 public:
  explicit DeadlockDetector(DeadlockDetectorConfig config = {});

  std::vector<DeadlockFinding> Detect(const DeadlockSnapshot& snapshot) const;

  /**
   * @brief 纯图论有向图环检测算法 (DFS 实现)
   * @param wfg_model 资源持有与等待模型
   * @return std::vector<std::vector<std::string>> 检测到的所有死锁环，
   *         每个环为 waiter -> resource -> holder 交替序列并闭合回起始任务
   */
  std::vector<std::vector<std::string>> DetectCycles(
      const ResourceAllocationModel& wfg_model) const;

 private:
  DeadlockDetectorConfig config_;
};

}  // namespace amr_dispatcher_core::dispatcher

#include "amr_dispatcher_core/dispatcher/deadlock_detector.hpp"

#include <algorithm>
#include <iterator>
#include <unordered_map>

namespace amr_dispatcher_core::dispatcher {

DeadlockDetector::DeadlockDetector(DeadlockDetectorConfig config)
    : config_(config) {}

std::vector<std::vector<std::string>> DeadlockDetector::DetectCycles(
    const ResourceAllocationModel& wfg_model) const {
  std::vector<std::vector<std::string>> cycles;

  // 1. 构建任务等待图 (Wait-For Graph)：
  // 任务 M1 等待资源 R，而 R 当前被 M2 持有 -> 有向边 M1 -> M2，并记下触发该边的资源
  //（环路径要以 waiter -> resource -> holder 交替记录）。
  // 同一 (等待者, 持有者) 只建一条边：多把锁指向同一持有者时不重复上报同一环，
  // 与改前 std::set 去重语义一致。
  struct WaitEdge {
    std::string holder;
    std::string resource_id;
  };
  std::unordered_map<std::string, std::vector<WaitEdge>> adj;
  for (const auto& [waiter_m, requested_resources] : wfg_model.waiting_for) {
    for (const auto& res_id : requested_resources) {
      auto it = wfg_model.held_by.find(res_id);
      if (it == wfg_model.held_by.end() || it->second == waiter_m) {
        continue;
      }
      auto& edges = adj[waiter_m];
      const bool duplicated =
          std::any_of(edges.begin(), edges.end(),
                      [&it](const WaitEdge& edge) { return edge.holder == it->second; });
      if (!duplicated) {
        edges.push_back(WaitEdge{it->second, res_id});
      }
    }
  }

  // 2. 使用 DFS 进行拓扑三色标记法或路径回溯检测有向图环
  // 0: 未访问, 1: 正在当前递归栈中 (在探索), 2: 已完成探索
  // path 只记任务节点；path_res[i] 记 path[i] -> path[i+1] 所等待的资源。
  std::unordered_map<std::string, int> visit_state;
  std::vector<std::string> path;
  std::vector<std::string> path_res;

  auto dfs = [&](auto& self, const std::string& u) -> void {
    visit_state[u] = 1;
    path.push_back(u);

    auto it = adj.find(u);
    if (it != adj.end()) {
      for (const auto& edge : it->second) {
        const std::string& v = edge.holder;
        if (visit_state[v] == 1) {
          // 找到环！自栈上 v 起提取到当前 u，段间用 path_res 的资源，
          // 末段用回边 (u -> v) 的资源并闭合回 v：
          //   [v, res, ..., u, res, v] —— 任务与资源交替，死锁可视化的
          //   deadlocked_nodes 由其中的 route_edge:/route_node: 项解析而来。
          const auto cycle_start = std::find(path.begin(), path.end(), v);
          if (cycle_start != path.end()) {
            const auto start_index =
                static_cast<std::size_t>(std::distance(path.begin(), cycle_start));
            std::vector<std::string> cycle;
            for (std::size_t index = start_index; index < path.size(); ++index) {
              cycle.push_back(path[index]);
              cycle.push_back(index + 1 < path.size() ? path_res[index]
                                                      : edge.resource_id);
            }
            cycle.push_back(path[start_index]);  // 闭合回起始任务
            cycles.push_back(cycle);
          }
        } else if (visit_state[v] == 0) {
          path_res.push_back(edge.resource_id);
          self(self, v);
          path_res.pop_back();
        }
      }
    }

    path.pop_back();
    visit_state[u] = 2;
  };

  // 起点按字典序遍历：同一张图的环报告次序可复现（unordered_map 顺序不稳定）
  std::vector<std::string> start_nodes;
  start_nodes.reserve(adj.size());
  for (const auto& [node, _] : adj) {
    start_nodes.push_back(node);
  }
  std::sort(start_nodes.begin(), start_nodes.end());
  for (const auto& node : start_nodes) {
    if (visit_state[node] == 0) {
      dfs(dfs, node);
    }
  }

  return cycles;
}

std::vector<DeadlockFinding> DeadlockDetector::Detect(
    const DeadlockSnapshot& snapshot) const {
  std::vector<DeadlockFinding> findings;
  const auto now = std::chrono::steady_clock::now();

  // 1. 【严密图论判定】通过 Wait-For Graph 进行 0 毫秒确定性死锁环检测
  const auto cycles = DetectCycles(snapshot.allocation_graph);
  for (const auto& cycle : cycles) {
    DeadlockFinding f;
    f.kind = DeadlockKind::kMutualBlock;
    f.cycle_path = cycle;
    // cycle_path 为任务/资源交替且首尾闭合：偶数位是任务，奇数位是资源，
    // mission_ids 只取任务（recovery 据此对任务下发暂停/取消，不能混入资源 id）
    for (std::size_t i = 0; i + 1 < cycle.size(); i += 2) {
      f.mission_ids.push_back(cycle[i]);
    }
    std::string desc = "Wait-For Graph Cycle detected: [";
    for (size_t i = 0; i < cycle.size(); ++i) {
      desc += cycle[i];
      if (i + 1 < cycle.size()) desc += " -> ";
    }
    desc += "]";  // cycle_path 自身闭合回起始任务
    f.description = desc;
    findings.push_back(std::move(f));
  }

  // 2. 启发式活跃任务过多检测
  if (config_.max_active_missions > 0 &&
      snapshot.active_missions.size() > config_.max_active_missions) {
    DeadlockFinding f;
    f.kind = DeadlockKind::kMutualBlock;
    f.description = "too many active missions: " +
                    std::to_string(snapshot.active_missions.size());
    for (const auto& m : snapshot.active_missions) {
      f.mission_ids.push_back(m.id);
    }
    findings.push_back(std::move(f));
  }

  // 3. 启发式：ACTIVE 但无 progress 超过阈值
  for (const auto& m : snapshot.active_missions) {
    auto it = snapshot.last_progress.find(m.id);
    if (it == snapshot.last_progress.end()) {
      continue;
    }
    if (now - it->second > config_.active_idle_threshold) {
      DeadlockFinding f;
      f.kind = DeadlockKind::kIdleActive;
      f.description = "mission idle too long: " + m.id;
      f.mission_ids.push_back(m.id);
      findings.push_back(std::move(f));
    }
  }

  // 4. 启发式：长期持锁检测
  std::unordered_map<std::string, std::vector<std::string>> resource_to_missions;
  for (const auto& m : snapshot.active_missions) {
    if (!m.reservation_id.empty()) {
      resource_to_missions[m.reservation_id].push_back(m.id);
    }
  }
  for (const auto& [resource, acquired_at] : snapshot.reservation_acquired_at) {
    if (now - acquired_at <= config_.reservation_hold_threshold) {
      continue;
    }
    auto it = resource_to_missions.find(resource);
    if (it == resource_to_missions.end() || it->second.empty()) {
      continue;
    }
    DeadlockFinding f;
    f.kind = DeadlockKind::kLongReservationHold;
    f.description = "resource held too long: " + resource;
    f.mission_ids = it->second;
    findings.push_back(std::move(f));
  }

  return findings;
}

}  // namespace amr_dispatcher_core::dispatcher

#include "amr_dispatcher_core/dispatcher/deadlock_detector.hpp"

#include <gtest/gtest.h>

using namespace amr_dispatcher_core::dispatcher;
using namespace std::chrono_literals;

namespace {

Mission Active(std::string id) {
  Mission m;
  m.id = std::move(id);
  m.state = MissionState::kActive;
  return m;
}

}  // namespace

TEST(DeadlockDetectorTest, EmptySnapshotNoFindings) {
  DeadlockDetector d;
  EXPECT_TRUE(d.Detect({}).empty());
}

TEST(DeadlockDetectorTest, TrueWaitForGraphCycleDetection) {
  DeadlockDetector d;
  DeadlockSnapshot snap;

  // 场景：两台车发生经典交叉死锁：
  // Robot A 持有 Edge 1，申请等待 Edge 2
  // Robot B 持有 Edge 2，申请等待 Edge 1
  snap.allocation_graph.held_by["edge_1"] = "robot_A";
  snap.allocation_graph.held_by["edge_2"] = "robot_B";

  snap.allocation_graph.waiting_for["robot_A"] = {"edge_2"};
  snap.allocation_graph.waiting_for["robot_B"] = {"edge_1"};

  snap.active_missions = {Active("robot_A"), Active("robot_B")};

  const auto findings = d.Detect(snap);
  ASSERT_FALSE(findings.empty());
  EXPECT_EQ(findings[0].kind, DeadlockKind::kMutualBlock);
  EXPECT_EQ(findings[0].mission_ids.size(), 2u);
  EXPECT_NE(findings[0].description.find("Cycle detected"), std::string::npos);
}

TEST(DeadlockDetectorTest, MultiNodeCircularWaitCycle) {
  DeadlockDetector d;
  ResourceAllocationModel model;

  // 3车环形死锁：A等B持有的R2，B等C持有的R3，C等A持有的R1
  model.held_by["R1"] = "car_A";
  model.held_by["R2"] = "car_B";
  model.held_by["R3"] = "car_C";

  model.waiting_for["car_A"] = {"R2"};
  model.waiting_for["car_B"] = {"R3"};
  model.waiting_for["car_C"] = {"R1"};

  const auto cycles = d.DetectCycles(model);
  ASSERT_EQ(cycles.size(), 1u);
  // 交替格式：任务、其等待的资源、持有者 …… 末位闭合回起始任务
  EXPECT_EQ(cycles[0], (std::vector<std::string>{"car_A", "R2", "car_B", "R3", "car_C", "R1",
                                                 "car_A"}));
}

TEST(DeadlockDetectorTest, MutualBlockFindingPathKeepsResourcesAndMissionsApart) {
  DeadlockDetector d;
  DeadlockSnapshot snap;

  // 两车互持互等：cycle_path 必须带资源 id（Task 3 deadlocked_nodes 端到端解析依赖），
  // mission_ids 必须只含任务 id（recovery 按任务 id 下发暂停/取消）
  snap.allocation_graph.held_by["route_edge:A__B"] = "robot_A";
  snap.allocation_graph.held_by["route_node:C"] = "robot_B";
  snap.allocation_graph.waiting_for["robot_A"] = {"route_node:C"};
  snap.allocation_graph.waiting_for["robot_B"] = {"route_edge:A__B"};
  snap.active_missions = {Active("robot_A"), Active("robot_B")};

  const auto findings = d.Detect(snap);
  ASSERT_FALSE(findings.empty());
  EXPECT_EQ(findings[0].kind, DeadlockKind::kMutualBlock);
  EXPECT_EQ(findings[0].cycle_path,
            (std::vector<std::string>{"robot_A", "route_node:C", "robot_B", "route_edge:A__B",
                                      "robot_A"}));
  EXPECT_EQ(findings[0].mission_ids, (std::vector<std::string>{"robot_A", "robot_B"}));
}

TEST(DeadlockDetectorTest, DetectCycles_MultipleResourcesSameHolder_EmitsSingleEdge) {
  DeadlockDetector d;
  ResourceAllocationModel model;

  // car_A 等 car_B 持有的两把锁：任务对 (A->B) 只建一条等待边，
  // 否则同一环会因每把锁重复上报（与改前 set 去重语义一致）
  model.held_by["R1"] = "car_B";
  model.held_by["R2"] = "car_B";
  model.held_by["R3"] = "car_A";
  model.waiting_for["car_A"] = {"R1", "R2"};
  model.waiting_for["car_B"] = {"R3"};

  const auto cycles = d.DetectCycles(model);
  ASSERT_EQ(cycles.size(), 1u);
  EXPECT_EQ(cycles[0], (std::vector<std::string>{"car_A", "R1", "car_B", "R3", "car_A"}));
}

TEST(DeadlockDetectorTest, NoCycleWhenWaitGraphIsDAG) {
  DeadlockDetector d;
  ResourceAllocationModel model;

  // 有向无环图 (DAG)：A 等 B，B 等 C，C 不等待任何资源 -> 无死锁
  model.held_by["R1"] = "car_B";
  model.held_by["R2"] = "car_C";

  model.waiting_for["car_A"] = {"R1"};
  model.waiting_for["car_B"] = {"R2"};

  const auto cycles = d.DetectCycles(model);
  EXPECT_TRUE(cycles.empty());
}

TEST(DeadlockDetectorTest, TooManyActiveMissions) {
  DeadlockDetector d({.max_active_missions = 2});
  DeadlockSnapshot snap;
  snap.active_missions = {Active("a"), Active("b"), Active("c")};
  const auto findings = d.Detect(snap);
  ASSERT_FALSE(findings.empty());
  EXPECT_EQ(findings[0].kind, DeadlockKind::kMutualBlock);
  EXPECT_EQ(findings[0].mission_ids.size(), 3u);
}

TEST(DeadlockDetectorTest, IdleActiveDetected) {
  DeadlockDetector d({.max_active_missions = 100,
                     .active_idle_threshold = 100ms});
  DeadlockSnapshot snap;
  snap.active_missions = {Active("a")};
  snap.last_progress["a"] = std::chrono::steady_clock::now() - 500ms;
  const auto findings = d.Detect(snap);
  ASSERT_FALSE(findings.empty());
  EXPECT_EQ(findings[0].kind, DeadlockKind::kIdleActive);
  EXPECT_EQ(findings[0].mission_ids.front(), "a");
}

TEST(DeadlockDetectorTest, LongReservationHoldDetected) {
  DeadlockDetector d({.max_active_missions = 100,
                     .reservation_hold_threshold = 100ms});
  DeadlockSnapshot snap;
  Mission a = Active("a");
  a.reservation_id = "edge_1_2";
  snap.active_missions = {a};
  snap.reservation_acquired_at["edge_1_2"] = std::chrono::steady_clock::now() - 500ms;
  snap.reserved_resource_ids.insert("edge_1_2");
  const auto findings = d.Detect(snap);
  ASSERT_FALSE(findings.empty());
  EXPECT_EQ(findings[0].kind, DeadlockKind::kLongReservationHold);
}

