// A2(d)：降级（新丢包）清除未消费的恢复信号
TEST(LinkQualityTest, NewLossClearsPendingRecoverySignal) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 5, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 10; ++i) {
    q.RecordLoss();
  }
  for (int i = 0; i < 5; ++i) {
    q.RecordSuccess(1.0);
  }
  ASSERT_TRUE(q.ConsumeRecoverySignal());
  for (int i = 0; i < 5; ++i) {
    q.RecordSuccess(1.0);  // 继续成功不重复触发
  }
  EXPECT_FALSE(q.ConsumeRecoverySignal());
  q.RecordLoss();  // 新降级：若期间有未消费信号应被清除
  for (int i = 0; i < 5; ++i) {
    q.RecordSuccess(1.0);
  }
  // 重新达阈值后可以再次触发（这是新一轮恢复，不是旧信号残留）
  EXPECT_TRUE(q.ConsumeRecoverySignal());
  EXPECT_FALSE(q.ConsumeRecoverySignal());
}

