#include "amr_dispatcher_core/dispatcher/mission_cost_estimator.hpp"
#include "amr_dispatcher_core/dispatcher/dock_catalog.hpp"
#include "amr_dispatcher_core/path_tracking/geometry_utils.hpp"
#include "amr_dispatcher_core/safety/fault_supervisor.hpp"

#include <gtest/gtest.h>
#include <thread>

using namespace amr_dispatcher_core::dispatcher;
using namespace amr_dispatcher_core::path_tracking;
using namespace amr_dispatcher_core::safety;
using namespace std::chrono_literals;

// 1. 几何与角度测试
TEST(GeometryUtilsTest, NormalizesAngleWrapAround) {
  EXPECT_NEAR(NormalizeAngle(0.0), 0.0, 1e-6);
  EXPECT_NEAR(NormalizeAngle(3.0 * M_PI), M_PI, 1e-6);
  EXPECT_NEAR(NormalizeAngle(-3.0 * M_PI), -M_PI, 1e-6);
  EXPECT_NEAR(AngleDifference(0.1, -0.1), 0.2, 1e-6);
}

TEST(GeometryUtilsTest, Quaternion2DYawRoundTrip) {
  double yaw = 1.25;
  auto q = QuaternionFromYaw(yaw);
  double recovered = YawFromQuaternion(q.z, q.w);
  EXPECT_NEAR(recovered, yaw, 1e-6);
}

// 2. 成本与电量估算测试
TEST(MissionCostEstimatorTest, CalculatesTravelTimeAndBatteryDrop) {
  CostEstimatorConfig cfg;
  cfg.nominal_linear_speed_mps = 1.0;
  cfg.battery_drop_per_meter_v = 0.01;
  cfg.minimum_safe_voltage_v = 22.0;
  cfg.station_stop_penalty_sec = 2.0;

  MissionCostEstimator estimator(cfg);

  // 100 米，3 个停靠点，当前电压 24V
  auto est = estimator.Estimate(100.0, 3, 24.0);
  EXPECT_DOUBLE_EQ(est.distance_m, 100.0);
  EXPECT_DOUBLE_EQ(est.eta_seconds, 100.0 + (3 - 1) * 2.0);  // 104 秒
  EXPECT_DOUBLE_EQ(est.estimated_battery_drop_v, 1.0);       // 100 * 0.01 = 1V
  EXPECT_DOUBLE_EQ(est.projected_battery_voltage, 23.0);
  EXPECT_TRUE(est.battery_sufficient);

  // 极低电量测试
  auto low_est = estimator.Estimate(100.0, 1, 22.5);
  EXPECT_FALSE(low_est.battery_sufficient);  // 22.5 - 1.0 = 21.5V < 22.0V
}

// 3. 充电桩管理测试
TEST(DockCatalogTest, ManagesChargingStations) {
  DockCatalog catalog;
  ChargingDock d1{"dock_01", "st_charge_1", "st_approach_1", "lock_chg_1", true, false, ""};
  catalog.AddDock(d1);

  ASSERT_NE(catalog.FindDock("dock_01"), nullptr);
  EXPECT_EQ(catalog.FindAvailableDock()->id, "dock_01");

  EXPECT_TRUE(catalog.OccupyDock("dock_01", "robot_01"));
  EXPECT_EQ(catalog.FindAvailableDock(), nullptr);  // 已被占用，无可用

  EXPECT_TRUE(catalog.ReleaseDock("dock_01"));
  EXPECT_NE(catalog.FindAvailableDock(), nullptr);  // 释放后恢复可用
}

// 4. 故障监督状态机测试
TEST(FaultSupervisorTest, TransitionsThroughGraceAndFault) {
  SupervisorConfig cfg;
  cfg.startup_grace = 100ms;
  cfg.command_cooldown = 10ms;
  cfg.auto_clear = true;

  FaultSupervisor supervisor(cfg);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kWaiting);

  // 启动宽限期内出现错误 -> 处于 ARMING
  supervisor.UpdateHealth(false, "sensor warm-up");
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kArming);

  // 超出启动宽限期 -> 触发 FAULT 与急停请求
  std::this_thread::sleep_for(120ms);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kFault);
  EXPECT_TRUE(supervisor.emergency_stop_requested());

  // 恢复健康 -> 自愈恢复并清除急停
  supervisor.UpdateHealth(true, "healthy");
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kRecovery);
  EXPECT_FALSE(supervisor.emergency_stop_requested());

  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kNormal);
}

TEST(FaultSupervisorTest, MultiSourceArbitrationRecommendations) {
  SupervisorConfig cfg;
  cfg.startup_grace = 50ms;
  cfg.command_cooldown = 10ms;
  cfg.auto_clear = true;
  cfg.degraded_loss_rate_threshold = 0.15;
  cfg.critical_loss_rate_threshold = 0.35;

  FaultSupervisor supervisor(cfg);
  std::this_thread::sleep_for(60ms);

  // 1. 中度丢包率 20% -> 建议限速 ClampSpeed
  MultiSourceHealthReport r1;
  r1.chassis_healthy = false;
  r1.chassis_loss_rate = 0.20;
  supervisor.UpdateMultiSourceHealth(r1);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kDegraded);
  EXPECT_EQ(supervisor.recommendation(), SystemActionRecommendation::kClampSpeed);

  // 2. 严重丢包率 40% -> 触发 FAULT 且建议 EmergencyStop
  MultiSourceHealthReport r2;
  r2.chassis_loss_rate = 0.40;
  supervisor.UpdateMultiSourceHealth(r2);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kFault);
  EXPECT_EQ(supervisor.recommendation(), SystemActionRecommendation::kEmergencyStop);
  EXPECT_TRUE(supervisor.emergency_stop_requested());

  // 3. 死锁检测激活 -> 建议 PauseDispatch 暂缓接单
  MultiSourceHealthReport r3;
  r3.deadlock_detected = true;
  supervisor.UpdateMultiSourceHealth(r3);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kDegraded);
  EXPECT_EQ(supervisor.recommendation(), SystemActionRecommendation::kPauseDispatch);
}

// A3(a)：上报健康后停止刷新超过 staleness_timeout，Tick 将该数据视为不可信 -> 降级限速
TEST(FaultSupervisorTest, StaleReportDegradesAfterTimeout) {
  SupervisorConfig cfg;
  cfg.startup_grace = 0ms;
  cfg.staleness_timeout = 50ms;
  FaultSupervisor supervisor(cfg);

  MultiSourceHealthReport r;  // 全部健康（默认值）
  supervisor.UpdateMultiSourceHealth(r);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kNormal);

  // 数据源停止刷新超过 staleness_timeout：健康值不采信 -> 降级限速，不急停
  std::this_thread::sleep_for(70ms);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kDegraded);
  EXPECT_EQ(supervisor.recommendation(), SystemActionRecommendation::kClampSpeed);
  EXPECT_FALSE(supervisor.emergency_stop_requested());
}

// A3(b)：持续上报（间隔 < staleness_timeout）的源不受时效仲裁影响
TEST(FaultSupervisorTest, FreshReportsKeepNormal) {
  SupervisorConfig cfg;
  cfg.startup_grace = 0ms;
  cfg.staleness_timeout = 80ms;
  FaultSupervisor supervisor(cfg);

  MultiSourceHealthReport r;
  for (int i = 0; i < 4; ++i) {
    supervisor.UpdateMultiSourceHealth(r);  // 持续上报
    std::this_thread::sleep_for(30ms);
    supervisor.Tick();
    EXPECT_EQ(supervisor.state(), SupervisorState::kNormal);
    EXPECT_EQ(supervisor.recommendation(), SystemActionRecommendation::kNone);
  }
}

// A3(c)：从未上报过的源不参与时效判定 —— 不误判为急停/死锁，只按现状保持等待或降级
TEST(FaultSupervisorTest, NeverReportedSourcesAreNotJudged) {
  SupervisorConfig cfg;
  cfg.staleness_timeout = 50ms;
  FaultSupervisor supervisor(cfg);

  // 从未上报：停留在 WAITING，不产生任何故障判定
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kWaiting);

  // 只经基础接口上报 chassis/watchdog（estop/deadlock 源从未上报）。
  // 超时后 chassis/watchdog 不可信 -> 降级限速；未上报的 estop 源不得被误判为急停。
  supervisor.UpdateHealth(true, "ok");
  std::this_thread::sleep_for(70ms);
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kDegraded);
  EXPECT_EQ(supervisor.recommendation(), SystemActionRecommendation::kClampSpeed);
  EXPECT_FALSE(supervisor.emergency_stop_requested());
}

// A3：人工急停按最后已知值锁存 —— 报告过期不清除安全信号
TEST(FaultSupervisorTest, StaleReportKeepsActiveEstopLatched) {
  SupervisorConfig cfg;
  cfg.staleness_timeout = 50ms;
  FaultSupervisor supervisor(cfg);

  MultiSourceHealthReport r;
  r.manual_estop = true;
  supervisor.UpdateMultiSourceHealth(r);
  supervisor.Tick();
  ASSERT_EQ(supervisor.state(), SupervisorState::kFault);
  ASSERT_TRUE(supervisor.emergency_stop_requested());

  std::this_thread::sleep_for(70ms);  // 报告过期
  supervisor.Tick();
  EXPECT_EQ(supervisor.state(), SupervisorState::kFault);
  EXPECT_TRUE(supervisor.emergency_stop_requested());
}

#include "amr_dispatcher_core/chassis/link_quality.hpp"

#include <gtest/gtest.h>

using namespace amr_dispatcher_core::chassis;

TEST(LinkQualityTest, EmptyIsUnknown) {
  LinkQualityMonitor q;
  EXPECT_EQ(q.CurrentTier(), LinkHealthTier::kUnknown);
  EXPECT_FALSE(q.IsHealthy());
}

TEST(LinkQualityTest, AllSuccessBecomesHealthy) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 4, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 12; ++i) {
    q.RecordSuccess(5.0);
  }
  EXPECT_TRUE(q.IsHealthy());
  const auto s = q.Snapshot();
  EXPECT_EQ(s.frames_success, 12u);
  EXPECT_EQ(s.frames_lost, 0u);
  EXPECT_NEAR(s.loss_rate, 0.0, 1e-9);
}

TEST(LinkQualityTest, CrcErrorCountsAsLost) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 4, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 10; ++i) {
    q.RecordSuccess(1.0);
  }
  q.RecordCrcError();
  q.RecordCrcError();
  q.RecordCrcError();
  q.RecordLoss();
  const auto s = q.Snapshot();
  EXPECT_EQ(s.frames_crc_error, 3u);
  EXPECT_EQ(s.frames_lost, 4u);  // 3 crc + 1 explicit loss
  EXPECT_GT(s.loss_rate, 0.0);
}

TEST(LinkQualityTest, HighLossTriggersCritical) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 4, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 5; ++i) {
    q.RecordSuccess(1.0);
  }
  for (int i = 0; i < 20; ++i) {
    q.RecordLoss();
  }
  EXPECT_TRUE(q.IsCritical());
}

TEST(LinkQualityTest, RecoverySignalFiresAfterThreshold) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 5, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 10; ++i) {
    q.RecordLoss();
  }
  EXPECT_FALSE(q.ConsumeRecoverySignal());
  for (int i = 0; i < 5; ++i) {
    q.RecordSuccess(1.0);
  }
  EXPECT_TRUE(q.ConsumeRecoverySignal());
  EXPECT_FALSE(q.ConsumeRecoverySignal());  // consume once
}

TEST(LinkQualityTest, ResetClearsState) {
  LinkQualityMonitor q;
  q.RecordSuccess(1.0);
  q.RecordLoss();
  q.Reset();
  EXPECT_EQ(q.CurrentTier(), LinkHealthTier::kUnknown);
  EXPECT_EQ(q.Snapshot().frames_total, 0u);
}

TEST(LinkQualityTest, LatencyStatsTrackMax) {
  LinkQualityMonitor q;
  q.RecordSuccess(10.0);
  q.RecordSuccess(40.0);
  q.RecordSuccess(20.0);
  const auto s = q.Snapshot();
  EXPECT_DOUBLE_EQ(s.max_latency_ms, 40.0);
  EXPECT_DOUBLE_EQ(s.average_latency_ms, (10.0 + 40.0 + 20.0) / 3.0);
}

// A2(a)：长期健康（远超窗口长度全成功）后突发丢包，loss_rate 必须快速反映到
// degraded/critical —— 累计语义下 6/70 ≈ 0.086 测不出，会被长期健康稀释
TEST(LinkQualityTest, WindowedLossDetectsBurstAfterLongHealthy) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 4, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 64; ++i) {
    q.RecordSuccess(1.0);
  }
  EXPECT_TRUE(q.IsHealthy());
  for (int i = 0; i < 6; ++i) {
    q.RecordLoss();
  }
  // 窗口内 6/8 = 0.75 >= 0.15*2 -> critical
  EXPECT_TRUE(q.IsCritical());
  EXPECT_GE(q.Snapshot().loss_rate, 0.3);
}

// A2(b)：丢包消失且窗口滑过后自动恢复 kHealthy，无需 Reset（累计计数保留）
TEST(LinkQualityTest, SlidingWindowRecoversWithoutReset) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 4, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 8; ++i) {
    q.RecordLoss();
  }
  EXPECT_TRUE(q.IsCritical());
  for (int i = 0; i < 8; ++i) {
    q.RecordSuccess(1.0);
  }
  EXPECT_TRUE(q.IsHealthy());
  const auto s = q.Snapshot();
  EXPECT_EQ(s.frames_lost, 8u);  // 累计计数不丢历史
  EXPECT_DOUBLE_EQ(s.loss_rate, 0.0);
}

// A2(c)：window_size=0 构造不崩溃，钳到 1 后行为等价 window=1
TEST(LinkQualityTest, ZeroWindowSizeClampsToSingleSample) {
  LinkQualityMonitor q({.window_size = 0, .success_threshold = 4, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  q.RecordSuccess(1.0);  // 不崩溃
  q.RecordLoss();        // window=1：最新样本为 loss
  const auto s = q.Snapshot();
  EXPECT_EQ(s.frames_total, 2u);
  EXPECT_TRUE(s.loss_rate >= 0.99);  // 单样本窗口：loss_rate = 1.0
  EXPECT_FALSE(q.IsHealthy());
}

// A2(d)：恢复信号边沿化 —— 降级后连续成功 100 帧只触发一次
TEST(LinkQualityTest, RecoverySignalFiresOnceOverHundredSuccesses) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 5, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 10; ++i) {
    q.RecordLoss();
  }
  EXPECT_FALSE(q.ConsumeRecoverySignal());
  for (int i = 0; i < 100; ++i) {
    q.RecordSuccess(1.0);
  }
  EXPECT_TRUE(q.ConsumeRecoverySignal());   // 首次达阈值触发
  EXPECT_FALSE(q.ConsumeRecoverySignal());  // 只触发一次
  EXPECT_FALSE(q.ConsumeRecoverySignal());
}

// A2(d)：降级（新丢包）清除未消费的恢复信号；重新达标后可再次触发
TEST(LinkQualityTest, NewLossClearsPendingRecoverySignal) {
  LinkQualityMonitor q({.window_size = 8, .success_threshold = 5, .healthy_loss_rate = 0.02,
                        .degraded_loss_rate = 0.15});
  for (int i = 0; i < 10; ++i) {
    q.RecordLoss();
  }
  for (int i = 0; i < 5; ++i) {
    q.RecordSuccess(1.0);
  }
  // 恢复信号已就绪但尚未消费，此时出现新丢包（降级）应把它清除
  q.RecordLoss();
  EXPECT_FALSE(q.ConsumeRecoverySignal());  // 旧信号已清除，而非补发
  // 连续成功被新丢包打断后重新累计，达到阈值可再次触发（新一轮恢复）
  for (int i = 0; i < 5; ++i) {
    q.RecordSuccess(1.0);
  }
  EXPECT_TRUE(q.ConsumeRecoverySignal());
  EXPECT_FALSE(q.ConsumeRecoverySignal());
}

#include "amr_dispatcher_core/chassis/link_quality.hpp"

#include <algorithm>
#include <utility>

namespace amr_dispatcher_core::chassis {

LinkQualityMonitor::LinkQualityMonitor(LinkQualityConfig config)
    : config_(std::move(config)) {
  // window_size=0 属于非法配置：钳到 1，避免环形缓冲取模除零
  if (config_.window_size == 0) {
    config_.window_size = 1;
  }
  window_.assign(config_.window_size, Sample{});
}

void LinkQualityMonitor::RecordSuccess(const double latency_ms) {
  std::lock_guard<std::mutex> lock(mutex_);
  window_[head_] = Sample{true, latency_ms};
  head_ = (head_ + 1) % config_.window_size;
  if (window_filled_ < config_.window_size) {
    ++window_filled_;
  }
  ++total_success_;
  ++consecutive_success_;
  last_seen_ = std::chrono::steady_clock::now();

  // 恢复信号（边沿）：条件"连续成功达标且（按重算前的旧 tier）尚未恢复健康"
  // 从不满足变为满足的沿只置一次；latch 跟随条件电平，避免消费后立刻重发。
  const bool condition = consecutive_success_ >= config_.success_threshold &&
                         tier_ != LinkHealthTier::kHealthy;
  if (condition && !recovery_condition_latched_) {
    pending_recovery_signal_ = true;
  }
  recovery_condition_latched_ = condition;

  RecomputeLocked();
}

void LinkQualityMonitor::RecordLoss() {
  std::lock_guard<std::mutex> lock(mutex_);
  window_[head_] = Sample{false, 0.0};
  head_ = (head_ + 1) % config_.window_size;
  if (window_filled_ < config_.window_size) {
    ++window_filled_;
  }
  ++total_lost_;
  consecutive_success_ = 0;
  last_seen_ = std::chrono::steady_clock::now();
  // 新丢包降级：清除未消费的恢复信号与条件电平（下一轮恢复重新取沿）
  pending_recovery_signal_ = false;
  recovery_condition_latched_ = false;
  RecomputeLocked();
}

void LinkQualityMonitor::RecordCrcError() {
  std::lock_guard<std::mutex> lock(mutex_);
  window_[head_] = Sample{false, 0.0};
  head_ = (head_ + 1) % config_.window_size;
  if (window_filled_ < config_.window_size) {
    ++window_filled_;
  }
  ++total_crc_error_;
  ++total_lost_;
  consecutive_success_ = 0;
  pending_recovery_signal_ = false;
  recovery_condition_latched_ = false;
  RecomputeLocked();
}

void LinkQualityMonitor::RecomputeLocked() {
  cached_snapshot_.frames_total = total_success_ + total_lost_;
  cached_snapshot_.frames_success = total_success_;
  cached_snapshot_.frames_lost = total_lost_;
  cached_snapshot_.frames_crc_error = total_crc_error_;
  cached_snapshot_.last_seen = last_seen_;

  // 真滑动窗口：只统计 ring 中最近 window_filled_ 个样本的丢包与时延。
  // 累计计数（frames_*）只保留历史总量，不参与 loss_rate / tier 判定，
  // 否则长期健康的累计基数会把突发丢包稀释得测不出来。
  std::size_t window_losses = 0;
  std::size_t window_success = 0;
  double window_latency_sum_ms = 0.0;
  double window_latency_max_ms = 0.0;
  for (std::size_t i = 0; i < window_filled_; ++i) {
    const auto& sample = window_[(head_ + window_.size() - window_filled_ + i) % window_.size()];
    if (sample.success) {
      ++window_success;
      window_latency_sum_ms += sample.latency_ms;
      window_latency_max_ms = std::max(window_latency_max_ms, sample.latency_ms);
    } else {
      ++window_losses;
    }
  }

  if (window_filled_ == 0) {
    cached_snapshot_.loss_rate = 0.0;
    cached_snapshot_.average_latency_ms = 0.0;
    cached_snapshot_.max_latency_ms = 0.0;
    tier_ = LinkHealthTier::kUnknown;
    cached_snapshot_.tier = tier_;
    return;
  }
  cached_snapshot_.loss_rate =
      static_cast<double>(window_losses) / static_cast<double>(window_filled_);
  cached_snapshot_.average_latency_ms =
      window_success > 0 ? window_latency_sum_ms / static_cast<double>(window_success) : 0.0;
  cached_snapshot_.max_latency_ms = window_latency_max_ms;

  // 优先级：critical > degraded > healthy > unknown
  if (cached_snapshot_.loss_rate >= config_.degraded_loss_rate * 2.0) {
    tier_ = LinkHealthTier::kCritical;
  } else if (cached_snapshot_.loss_rate >= config_.degraded_loss_rate) {
    tier_ = LinkHealthTier::kDegraded;
  } else if (cached_snapshot_.loss_rate <= config_.healthy_loss_rate &&
             consecutive_success_ >= config_.success_threshold) {
    tier_ = LinkHealthTier::kHealthy;
  } else if (tier_ == LinkHealthTier::kUnknown) {
    tier_ = LinkHealthTier::kDegraded;
  }
  cached_snapshot_.tier = tier_;
}

LinkQualitySnapshot LinkQualityMonitor::Snapshot() const {
  std::lock_guard<std::mutex> lock(mutex_);
  return cached_snapshot_;
}

LinkHealthTier LinkQualityMonitor::CurrentTier() const {
  std::lock_guard<std::mutex> lock(mutex_);
  return tier_;
}

bool LinkQualityMonitor::IsHealthy() const {
  std::lock_guard<std::mutex> lock(mutex_);
  return tier_ == LinkHealthTier::kHealthy;
}

bool LinkQualityMonitor::IsCritical() const {
  std::lock_guard<std::mutex> lock(mutex_);
  return tier_ == LinkHealthTier::kCritical;
}

bool LinkQualityMonitor::ConsumeRecoverySignal() {
  std::lock_guard<std::mutex> lock(mutex_);
  if (!pending_recovery_signal_) {
    return false;
  }
  pending_recovery_signal_ = false;
  return true;
}

void LinkQualityMonitor::Reset() {
  std::lock_guard<std::mutex> lock(mutex_);
  std::fill(window_.begin(), window_.end(), Sample{});
  head_ = 0;
  window_filled_ = 0;
  total_success_ = 0;
  total_lost_ = 0;
  total_crc_error_ = 0;
  consecutive_success_ = 0;
  pending_recovery_signal_ = false;
  recovery_condition_latched_ = false;
  cached_snapshot_ = LinkQualitySnapshot{};
  tier_ = LinkHealthTier::kUnknown;
}

}  // namespace amr_dispatcher_core::chassis

#pragma once

#include <chrono>
#include <cstddef>
#include <cstdint>
#include <mutex>
#include <string>
#include <vector>

namespace amr_dispatcher_core::chassis {

// 链路质量统计：真滑动窗口丢包率、CRC 错误率、平均时延、最大时延。
// 窗口指标只统计最近 window_size 个样本（突发丢包不被长期健康稀释）；
// frames_* 累计计数保留历史总量。线程安全（内部 mutex 保护），单 chassis_backend 复用一份。
struct LinkQualityConfig {
  std::size_t window_size = 64;           // 滑动窗口样本数（0 会被钳到 1）
  std::size_t success_threshold = 50;     // 连续成功帧数到该值视为恢复良好
  double healthy_loss_rate = 0.02;        // 健康上限（窗口内丢包率 <= 该值）
  double degraded_loss_rate = 0.15;       // 降级阈值（超过进入 degraded）
};

enum class LinkHealthTier {
  kUnknown,
  kHealthy,
  kDegraded,
  kCritical,
};

struct LinkQualitySnapshot {
  std::size_t frames_total = 0;
  std::size_t frames_success = 0;
  std::size_t frames_lost = 0;
  std::size_t frames_crc_error = 0;
  double loss_rate = 0.0;                 // 窗口内丢包率（含 CRC 错误），不被长期健康稀释
  double average_latency_ms = 0.0;
  double max_latency_ms = 0.0;
  std::chrono::steady_clock::time_point last_seen{};
  LinkHealthTier tier = LinkHealthTier::kUnknown;
};

class LinkQualityMonitor {
 public:
  explicit LinkQualityMonitor(LinkQualityConfig config = {});

  // 每次从后端收到一帧时调用：success 表示解码成功；latency 为从写入命令到收到对应反馈的往返时延（若无填 0）。
  void RecordSuccess(double latency_ms);
  void RecordLoss();
  void RecordCrcError();

  LinkQualitySnapshot Snapshot() const;
  LinkHealthTier CurrentTier() const;

  // 健康判定
  bool IsHealthy() const;
  bool IsCritical() const;
  // 恢复信号（边沿语义）：进入"连续成功达标且尚未恢复健康"条件首次满足时置位，
  // 消费后清零；Reset 或新丢包（降级）时清除。用于触发后端回切。
  bool ConsumeRecoverySignal();

  void Reset();

 private:
  struct Sample {
    bool success = false;
    double latency_ms = 0.0;
  };

  void RecomputeLocked();

  LinkQualityConfig config_;
  mutable std::mutex mutex_;
  std::vector<Sample> window_;
  std::size_t head_ = 0;
  std::size_t window_filled_ = 0;
  std::size_t total_success_ = 0;
  std::size_t total_lost_ = 0;
  std::size_t total_crc_error_ = 0;
  std::size_t consecutive_success_ = 0;
  bool pending_recovery_signal_ = false;      // 恢复信号（边沿触发，只置一次）
  bool recovery_condition_latched_ = false;   // 恢复条件上一次的电平（用于取沿）
  std::chrono::steady_clock::time_point last_seen_{};
  LinkHealthTier tier_ = LinkHealthTier::kUnknown;
  LinkQualitySnapshot cached_snapshot_{};
};

}  // namespace amr_dispatcher_core::chassis

