20	std::string FormatLogRecord(const LogRecord& record) {
21	  std::time_t t = std::chrono::system_clock::to_time_t(record.stamp);
22	  std::tm tm{};
23	  gmtime_r(&t, &tm);
24	  char buf[32];
25	  std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", &tm);
26	  std::ostringstream out;
27	  out << buf << " " << LevelToString(record.level) << " "
28	      << record.component << ": " << record.message;
29	  return out.str();
30	}
