32	// =================== SyncLogger ===================
33	
34	SyncLogger::SyncLogger(std::string path, LogLevel min_level)
35	    : path_(std::move(path)), min_level_(min_level),
36	      stream_(path_, std::ios::app) {}
37	
38	SyncLogger::~SyncLogger() {
39	  if (stream_.is_open()) {
40	    stream_.flush();
41	  }
42	}
