44	void SyncLogger::Log(const LogLevel level, const std::string& component,
45	                     const std::string& message) {
46	  if (static_cast<int>(level) < static_cast<int>(min_level_)) {
47	    return;
48	  }
49	  LogRecord r;
50	  r.level = level;
51	  r.component = component;
52	  r.message = message;
53	  if (stream_.is_open()) {
54	    stream_ << FormatLogRecord(r) << "\n";
55	  }
56	}
57	
58	void SyncLogger::Flush() {
59	  if (stream_.is_open()) {
60	    stream_.flush();
61	  }
62	}
63	
64	// =================== AsyncLogger ===================
65	
