  ASSERT_TRUE(backend.WriteCommand(cmd, &error)) << error;

  const std::string received = ReadUntilNewline(pty.master, 500ms);
  EXPECT_EQ(received, "CMD 1.5000 -0.5000 0.2500\n");
}

