// 而不是旧语义的"假装成功"
TEST(SerialBackendTest, WouldBlockReturnsFalse) {
  PtyPair pty = OpenPty();
  ASSERT_GE(pty.master, 0);

  ChassisBackendConfig cfg;
  cfg.serial_device = pty.slave_path;
  cfg.serial_baud = 115200;
