  if (sent < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
    if (error != nullptr) {
      *error = std::strerror(errno);
    }
    return false;
  }
  return sent >= 0 || errno == EAGAIN || errno == EWOULDBLOCK;
}

