  ChassisCommand cmd{.linear_x_mps = 1.5, .linear_y_mps = -0.5, .angular_z_radps = 0.25};
  ASSERT_TRUE(backend.WriteCommand(cmd, &error)) << error;

  char buf[512];
  const ssize_t n = recv(recv_fd, buf, sizeof(buf), 0);
