24	TEST(DeadlockDetectorTest, TrueWaitForGraphCycleDetection) {
25	  DeadlockDetector d;
26	  DeadlockSnapshot snap;
27	
28	  // 场景：两台车发生经典交叉死锁：
29	  // Robot A 持有 Edge 1，申请等待 Edge 2
30	  // Robot B 持有 Edge 2，申请等待 Edge 1
31	  snap.allocation_graph.held_by["edge_1"] = "robot_A";
32	  snap.allocation_graph.held_by["edge_2"] = "robot_B";
33	
34	  snap.allocation_graph.waiting_for["robot_A"] = {"edge_2"};
35	  snap.allocation_graph.waiting_for["robot_B"] = {"edge_1"};
36	
37	  snap.active_missions = {Active("robot_A"), Active("robot_B")};
38	
39	  const auto findings = d.Detect(snap);
40	  ASSERT_FALSE(findings.empty());
41	  EXPECT_EQ(findings[0].kind, DeadlockKind::kMutualBlock);
42	  EXPECT_EQ(findings[0].mission_ids.size(), 2u);
43	  EXPECT_NE(findings[0].description.find("Cycle detected"), std::string::npos);
44	}
