46	TEST(DeadlockDetectorTest, MultiNodeCircularWaitCycle) {
47	  DeadlockDetector d;
48	  ResourceAllocationModel model;
49	
50	  // 3车环形死锁：A等B持有的R2，B等C持有的R3，C等A持有的R1
51	  model.held_by["R1"] = "car_A";
52	  model.held_by["R2"] = "car_B";
53	  model.held_by["R3"] = "car_C";
54	
55	  model.waiting_for["car_A"] = {"R2"};
56	  model.waiting_for["car_B"] = {"R3"};
57	  model.waiting_for["car_C"] = {"R1"};
58	
59	  const auto cycles = d.DetectCycles(model);
60	  ASSERT_EQ(cycles.size(), 1u);
61	  // 交替格式：任务、其等待的资源、持有者 …… 末位闭合回起始任务
62	  EXPECT_EQ(cycles[0], (std::vector<std::string>{"car_A", "R2", "car_B", "R3", "car_C", "R1",
63	                                                 "car_A"}));
64	}
