66	TEST(DeadlockDetectorTest, MutualBlockFindingPathKeepsResourcesAndMissionsApart) {
67	  DeadlockDetector d;
68	  DeadlockSnapshot snap;
69	
70	  // 两车互持互等：cycle_path 必须带资源 id（Task 3 deadlocked_nodes 端到端解析依赖），
71	  // mission_ids 必须只含任务 id（recovery 按任务 id 下发暂停/取消）
72	  snap.allocation_graph.held_by["route_edge:A__B"] = "robot_A";
73	  snap.allocation_graph.held_by["route_node:C"] = "robot_B";
74	  snap.allocation_graph.waiting_for["robot_A"] = {"route_node:C"};
75	  snap.allocation_graph.waiting_for["robot_B"] = {"route_edge:A__B"};
76	  snap.active_missions = {Active("robot_A"), Active("robot_B")};
77	
78	  const auto findings = d.Detect(snap);
79	  ASSERT_FALSE(findings.empty());
80	  EXPECT_EQ(findings[0].kind, DeadlockKind::kMutualBlock);
81	  EXPECT_EQ(findings[0].cycle_path,
82	            (std::vector<std::string>{"robot_A", "route_node:C", "robot_B", "route_edge:A__B",
