#pragma once

#include <cstddef>
#include <string>
#include <vector>

#include "amr_dispatcher_core/chassis/chassis_packet.hpp"

namespace amr_dispatcher_core::chassis {

// 将字节流切分为文本协议数据包（每行一条，以 '\n' 结尾）。
// 内部维护粘包/半包缓冲：Append() 可任意切分追加，DrainPackets() 一次取干。
// 溢出语义（与 MickBinaryPacketStream 统一）：超限时清缓冲并置 Overflowed()
// 事件标志，流继续解析后续数据（不永久哑掉），ClearOverflow() 显式复位。
class ChassisPacketStream {
 public:
  explicit ChassisPacketStream(std::size_t max_buffer_bytes = 4096);

  void Append(const char* data, std::size_t size);
  void Append(const std::string& data);
  std::vector<ChassisPacket> DrainPackets();
  bool Overflowed() const;
  std::size_t InvalidLineCount() const;
  void ClearOverflow();
  void ClearInvalidLineCount();
  void Clear();

 private:
  std::size_t max_buffer_bytes_;
  std::string buffer_;
  std::vector<ChassisPacket> pending_packets_;
  bool overflowed_ = false;
  std::size_t invalid_line_count_ = 0;
};

// 将字节流切分为 Mick 二进制帧（0xAE 0xEA ... 0xEF 0xFE），带校验和。
// 溢出语义同 ChassisPacketStream：清缓冲 + Overflowed() 事件标志，不阻断后续解帧。
class MickBinaryPacketStream {
 public:
  explicit MickBinaryPacketStream(std::size_t max_buffer_bytes = 4096);

  void Append(const char* data, std::size_t size);
  void Append(const std::string& data);
  std::vector<ChassisPacket> DrainPackets();
  bool Overflowed() const;
  std::size_t InvalidFrameCount() const;
  void ClearOverflow();
  void ClearInvalidFrameCount();
  void Clear();

 private:
  std::size_t max_buffer_bytes_;
  std::vector<uint8_t> buffer_;
  bool overflowed_ = false;
  std::size_t invalid_frame_count_ = 0;
};

}  // namespace amr_dispatcher_core::chassis

#include "amr_dispatcher_core/chassis/chassis_packet_stream.hpp"

#include <algorithm>
#include <array>
#include <utility>

namespace amr_dispatcher_core::chassis {

ChassisPacketStream::ChassisPacketStream(const std::size_t max_buffer_bytes)
    : max_buffer_bytes_(max_buffer_bytes) {}

void ChassisPacketStream::Append(const char* data, const std::size_t size) {
  // A9：与二进制流统一 —— 溢出只置事件标志并清缓冲，不在此提前返回，
  // 否则流被永久哑掉、后续正常行再也解不出包。
  buffer_.append(data, size);
  if (buffer_.size() > max_buffer_bytes_) {
    // 丢弃超长坏行/积压（含本次刚追加的数据），置"曾发生溢出"事件位
    buffer_.clear();
    overflowed_ = true;
  }
  // 同步解析完整行：每解析完一行就从 buffer 摘掉，
  // 让 InvalidLineCount() 在 Append 之后即可见（无须 DrainPackets）。
  std::size_t newline = std::string::npos;
  while ((newline = buffer_.find('\n')) != std::string::npos) {
    const std::string line = buffer_.substr(0, newline);
    buffer_.erase(0, newline + 1);
    if (auto packet = ParsePacketLine(line)) {
      pending_packets_.push_back(*packet);
    } else if (!line.empty()) {
      ++invalid_line_count_;
    }
  }
}

void ChassisPacketStream::Append(const std::string& data) { Append(data.data(), data.size()); }

std::vector<ChassisPacket> ChassisPacketStream::DrainPackets() {
  std::vector<ChassisPacket> packets;
  packets.swap(pending_packets_);
  return packets;
}

bool ChassisPacketStream::Overflowed() const { return overflowed_; }

std::size_t ChassisPacketStream::InvalidLineCount() const { return invalid_line_count_; }

void ChassisPacketStream::ClearOverflow() { overflowed_ = false; }

void ChassisPacketStream::ClearInvalidLineCount() { invalid_line_count_ = 0; }

void ChassisPacketStream::Clear() {
  buffer_.clear();
  pending_packets_.clear();
  overflowed_ = false;
  invalid_line_count_ = 0;
}

MickBinaryPacketStream::MickBinaryPacketStream(const std::size_t max_buffer_bytes)
    : max_buffer_bytes_(max_buffer_bytes) {}

void MickBinaryPacketStream::Append(const char* data, const std::size_t size) {
  buffer_.insert(buffer_.end(), data, data + size);
  if (buffer_.size() > max_buffer_bytes_) {
    buffer_.clear();
    overflowed_ = true;
  }
}

void MickBinaryPacketStream::Append(const std::string& data) { Append(data.data(), data.size()); }

std::vector<ChassisPacket> MickBinaryPacketStream::DrainPackets() {
  std::vector<ChassisPacket> packets;
  while (buffer_.size() >= 7U) {
    const std::array<uint8_t, 2> magic{0xae, 0xea};
    const auto header = std::search(buffer_.begin(), buffer_.end(), magic.begin(), magic.end());
    if (header == buffer_.end()) {
      buffer_.clear();
      return packets;
    }
    buffer_.erase(buffer_.begin(), header);
    if (buffer_.size() < 7U) {
      return packets;
    }
    const std::size_t length = buffer_[2];
    const std::size_t total_length = 2U + 1U + length + 2U;
    if (length < 2U) {
      buffer_.erase(buffer_.begin());
      ++invalid_frame_count_;
      continue;
    }
    if (buffer_.size() < total_length) {
      return packets;
    }
    if (buffer_[total_length - 2U] != 0xef || buffer_[total_length - 1U] != 0xfe) {
      buffer_.erase(buffer_.begin());
      ++invalid_frame_count_;
      continue;
    }
    uint8_t checksum = 0;
    for (std::size_t i = 2; i < total_length - 3U; ++i) {
      checksum = static_cast<uint8_t>(checksum + buffer_[i]);
    }
    if (checksum != buffer_[total_length - 3U]) {
      buffer_.erase(buffer_.begin(), buffer_.begin() + total_length);
      ++invalid_frame_count_;
      continue;
    }
    MickBinaryFrame frame;
    frame.type = buffer_[3];
    frame.payload.assign(buffer_.begin() + 4, buffer_.begin() + total_length - 3U);
    if (auto packet = DecodeMickBinaryPacket(frame)) {
      packets.push_back(*packet);
    }
    buffer_.erase(buffer_.begin(), buffer_.begin() + total_length);
  }
  return packets;
}

bool MickBinaryPacketStream::Overflowed() const { return overflowed_; }

std::size_t MickBinaryPacketStream::InvalidFrameCount() const { return invalid_frame_count_; }

void MickBinaryPacketStream::ClearOverflow() { overflowed_ = false; }

void MickBinaryPacketStream::ClearInvalidFrameCount() { invalid_frame_count_ = 0; }

void MickBinaryPacketStream::Clear() {
  buffer_.clear();
  overflowed_ = false;
  invalid_frame_count_ = 0;
}

}  // namespace amr_dispatcher_core::chassis

#include "amr_dispatcher_core/chassis/chassis_packet_stream.hpp"

#include <gtest/gtest.h>

#include <string>

using amr_dispatcher_core::chassis::ChassisPacketKind;
using amr_dispatcher_core::chassis::ChassisPacketStream;
using amr_dispatcher_core::chassis::EncodeMickBinaryFrame;
using amr_dispatcher_core::chassis::MickBinaryPacketStream;

TEST(ChassisPacketStreamTest, DrainsCompleteLines) {
  ChassisPacketStream stream;
  stream.Append("ODOM 1 2 0.5 0.3 0.1\n");
  stream.Append("STATE running\n");
  const auto packets = stream.DrainPackets();
  ASSERT_EQ(packets.size(), 2u);
  EXPECT_EQ(packets[0].kind, ChassisPacketKind::kOdometry);
  EXPECT_EQ(packets[1].kind, ChassisPacketKind::kState);
}

TEST(ChassisPacketStreamTest, HandlesSplitPacketAcrossAppends) {
  ChassisPacketStream stream;
  stream.Append("ODOM 1 2 0.5 0.");
  EXPECT_TRUE(stream.DrainPackets().empty());
  stream.Append("3 0.1\n");
  const auto packets = stream.DrainPackets();
  ASSERT_EQ(packets.size(), 1u);
  EXPECT_DOUBLE_EQ(packets[0].odometry.linear_x_mps, 0.3);
}

TEST(ChassisPacketStreamTest, CountsInvalidLines) {
  ChassisPacketStream stream;
  stream.Append("GARBAGE\n");
  stream.Append("ODOM 1 2 0.5 0.3 0.1\n");
  EXPECT_EQ(stream.InvalidLineCount(), 1u);
  EXPECT_EQ(stream.DrainPackets().size(), 1u);
}

TEST(ChassisPacketStreamTest, OverflowClearsBuffer) {
  ChassisPacketStream stream(16);
  stream.Append("ODOM 1 2 0.5 0.3 0.1\n");
  // 溢出：整段缓冲（含这条已完整的行）被丢弃，事件位置位
  EXPECT_TRUE(stream.Overflowed());
  EXPECT_TRUE(stream.DrainPackets().empty());
  // A9：溢出不永久哑掉 —— 缓冲清空后自动恢复，后续正常行照常解包
  stream.Append("STATE running\n");
  EXPECT_EQ(stream.DrainPackets().size(), 1u);
}

TEST(ChassisPacketStreamTest, TrailingPartialLineIsKept) {
  ChassisPacketStream stream;
  stream.Append("STATE running\nODOM 1 2");
  const auto packets = stream.DrainPackets();
  ASSERT_EQ(packets.size(), 1u);
  EXPECT_EQ(packets[0].kind, ChassisPacketKind::kState);
  // 残留半包在下次 Append 后可继续解析
  stream.Append(" 0.5 0.3 0.1\n");
  EXPECT_EQ(stream.DrainPackets().size(), 1u);
}

// A9(a)：超长无 '\n' 行触发溢出后自动恢复 —— 后续正常行仍能解出包，
// Overflowed() 是"曾发生溢出"事件标志（解包成功后仍保持，ClearOverflow 可清）
TEST(ChassisPacketStreamTest, OverflowRecoversAndFlagStaysUntilCleared) {
  ChassisPacketStream stream(64);
  const std::string long_line(512, 'X');  // 远超 64 字节且不含 '\n'
  stream.Append(long_line);
  EXPECT_TRUE(stream.Overflowed());
  EXPECT_TRUE(stream.DrainPackets().empty());

  stream.Append("ODOM 1 2 0.5 0.3 0.1\n");
  const auto packets = stream.DrainPackets();
  ASSERT_EQ(packets.size(), 1u);
  EXPECT_EQ(packets[0].kind, ChassisPacketKind::kOdometry);

  EXPECT_TRUE(stream.Overflowed());  // 事件位不因解包成功而自动复位
  stream.ClearOverflow();
  EXPECT_FALSE(stream.Overflowed());
}

// A9(b)：二进制流溢出后语义一致 —— flag 为事件位、后续帧继续解析
TEST(MickBinaryPacketStreamTest, OverflowRecoversAndParsesNextFrame) {
  MickBinaryPacketStream stream(32);
  stream.Append(std::string(512, 'X'));  // 远超 32 → 溢出
  EXPECT_TRUE(stream.Overflowed());
  EXPECT_TRUE(stream.DrainPackets().empty());

  const auto frame = EncodeMickBinaryFrame(0xa2, {0x00});  // STATE running
  stream.Append(reinterpret_cast<const char*>(frame.data()), frame.size());
  const auto packets = stream.DrainPackets();
  ASSERT_EQ(packets.size(), 1u);
  EXPECT_EQ(packets[0].kind, ChassisPacketKind::kState);
  EXPECT_EQ(packets[0].state.status, "running");

  EXPECT_TRUE(stream.Overflowed());
  stream.ClearOverflow();
  EXPECT_FALSE(stream.Overflowed());
}

#include "amr_dispatcher_core/dispatcher/recovery_policy.hpp"

#include <unordered_set>

namespace amr_dispatcher_core::dispatcher {

RecoveryPolicy::RecoveryPolicy(RecoveryPolicyConfig config)
    : config_(config) {}

std::vector<RecoveryAction> RecoveryPolicy::Decide(
    const std::vector<DeadlockFinding>& findings,
    const std::function<std::size_t(const std::string&)>& attempt_of) const {
  std::vector<RecoveryAction> actions;
  std::unordered_set<std::string> seen;

  for (const auto& f : findings) {
    for (const auto& mid : f.mission_ids) {
      if (!seen.insert(mid).second) {
        continue;
      }
      const auto attempts = attempt_of ? attempt_of(mid) : 0;
      RecoveryAction action;
      action.mission_id = mid;
      action.reason = f.description;

      switch (f.kind) {
        case DeadlockKind::kIdleActive:
        case DeadlockKind::kLongReservationHold:
          if (attempts < config_.max_retries) {
            action.kind = RecoveryAction::Kind::kRetry;
          } else if (config_.auto_cancel_on_exhausted) {
            action.kind = RecoveryAction::Kind::kCancel;
          } else {
            action.kind = RecoveryAction::Kind::kPause;
          }
          break;
        case DeadlockKind::kMutualBlock:
          action.kind = RecoveryAction::Kind::kPause;
          break;
        case DeadlockKind::kOverCapacity:
          // A8：超容量是派发过载不是死锁 —— 不 pause 活跃任务（暂缓派发由
          // 派发侧限流负责），动作枚举中最贴近 hold 的处置是 kNone
          action.kind = RecoveryAction::Kind::kNone;
          break;
      }
      actions.push_back(std::move(action));
    }
  }
  return actions;
}

}  // namespace amr_dispatcher_core::dispatcher

#include "amr_dispatcher_core/dispatcher/deadlock_detector.hpp"

#include <algorithm>
#include <iterator>
#include <unordered_map>

namespace amr_dispatcher_core::dispatcher {

DeadlockDetector::DeadlockDetector(DeadlockDetectorConfig config)
    : config_(config) {}

std::vector<std::vector<std::string>> DeadlockDetector::DetectCycles(
    const ResourceAllocationModel& wfg_model) const {
  std::vector<std::vector<std::string>> cycles;

  // 1. 构建任务等待图 (Wait-For Graph)：
  // 任务 M1 等待资源 R，而 R 当前被 M2 持有 -> 有向边 M1 -> M2，并记下触发该边的资源
  //（环路径要以 waiter -> resource -> holder 交替记录）。
  // 同一 (等待者, 持有者) 只建一条边：多把锁指向同一持有者时不重复上报同一环，
  // 与改前 std::set 去重语义一致。
  struct WaitEdge {
    std::string holder;
    std::string resource_id;
  };
  std::unordered_map<std::string, std::vector<WaitEdge>> adj;
  for (const auto& [waiter_m, requested_resources] : wfg_model.waiting_for) {
    for (const auto& res_id : requested_resources) {
      auto it = wfg_model.held_by.find(res_id);
      if (it == wfg_model.held_by.end() || it->second == waiter_m) {
        continue;
      }
      auto& edges = adj[waiter_m];
      const bool duplicated =
          std::any_of(edges.begin(), edges.end(),
                      [&it](const WaitEdge& edge) { return edge.holder == it->second; });
      if (!duplicated) {
        edges.push_back(WaitEdge{it->second, res_id});
      }
    }
  }

  // 2. 使用 DFS 进行拓扑三色标记法或路径回溯检测有向图环
  // 0: 未访问, 1: 正在当前递归栈中 (在探索), 2: 已完成探索
  // path 只记任务节点；path_res[i] 记 path[i] -> path[i+1] 所等待的资源。
  std::unordered_map<std::string, int> visit_state;
  std::vector<std::string> path;
  std::vector<std::string> path_res;

  auto dfs = [&](auto& self, const std::string& u) -> void {
    visit_state[u] = 1;
    path.push_back(u);

    auto it = adj.find(u);
    if (it != adj.end()) {
      for (const auto& edge : it->second) {
        const std::string& v = edge.holder;
        if (visit_state[v] == 1) {
          // 找到环！自栈上 v 起提取到当前 u，段间用 path_res 的资源，
          // 末段用回边 (u -> v) 的资源并闭合回 v：
          //   [v, res, ..., u, res, v] —— 任务与资源交替，死锁可视化的
          //   deadlocked_nodes 由其中的 route_edge:/route_node: 项解析而来。
          const auto cycle_start = std::find(path.begin(), path.end(), v);
          if (cycle_start != path.end()) {
            const auto start_index =
                static_cast<std::size_t>(std::distance(path.begin(), cycle_start));
            std::vector<std::string> cycle;
            for (std::size_t index = start_index; index < path.size(); ++index) {
              cycle.push_back(path[index]);
              cycle.push_back(index + 1 < path.size() ? path_res[index]
                                                      : edge.resource_id);
            }
            cycle.push_back(path[start_index]);  // 闭合回起始任务
            cycles.push_back(cycle);
          }
        } else if (visit_state[v] == 0) {
          path_res.push_back(edge.resource_id);
          self(self, v);
          path_res.pop_back();
        }
      }
    }

    path.pop_back();
    visit_state[u] = 2;
  };

  // 起点按字典序遍历：同一张图的环报告次序可复现（unordered_map 顺序不稳定）
  std::vector<std::string> start_nodes;
  start_nodes.reserve(adj.size());
  for (const auto& [node, _] : adj) {
    start_nodes.push_back(node);
  }
  std::sort(start_nodes.begin(), start_nodes.end());
  for (const auto& node : start_nodes) {
    if (visit_state[node] == 0) {
      dfs(dfs, node);
    }
  }

  return cycles;
}

std::vector<DeadlockFinding> DeadlockDetector::Detect(
    const DeadlockSnapshot& snapshot) const {
  std::vector<DeadlockFinding> findings;
  const auto now = std::chrono::steady_clock::now();

  // 1. 【严密图论判定】通过 Wait-For Graph 进行 0 毫秒确定性死锁环检测
  const auto cycles = DetectCycles(snapshot.allocation_graph);
  for (const auto& cycle : cycles) {
    DeadlockFinding f;
    f.kind = DeadlockKind::kMutualBlock;
    f.cycle_path = cycle;
    // cycle_path 为任务/资源交替且首尾闭合：偶数位是任务，奇数位是资源，
    // mission_ids 只取任务（recovery 据此对任务下发暂停/取消，不能混入资源 id）
    for (std::size_t i = 0; i + 1 < cycle.size(); i += 2) {
      f.mission_ids.push_back(cycle[i]);
    }
    std::string desc = "Wait-For Graph Cycle detected: [";
    for (size_t i = 0; i < cycle.size(); ++i) {
      desc += cycle[i];
      if (i + 1 < cycle.size()) desc += " -> ";
    }
    desc += "]";  // cycle_path 自身闭合回起始任务
    f.description = desc;
    findings.push_back(std::move(f));
  }

  // 2. 启发式活跃任务过多检测（派发过载，独立于互斥死锁 kind，避免 recovery 误 pause）
  if (config_.max_active_missions > 0 &&
      snapshot.active_missions.size() > config_.max_active_missions) {
    DeadlockFinding f;
    f.kind = DeadlockKind::kOverCapacity;
    f.description = "too many active missions: " +
                    std::to_string(snapshot.active_missions.size());
    for (const auto& m : snapshot.active_missions) {
      f.mission_ids.push_back(m.id);
    }
    findings.push_back(std::move(f));
  }

  // 3. 启发式：ACTIVE 但无 progress 超过阈值
  for (const auto& m : snapshot.active_missions) {
    auto it = snapshot.last_progress.find(m.id);
    if (it == snapshot.last_progress.end()) {
      continue;
    }
    if (now - it->second > config_.active_idle_threshold) {
      DeadlockFinding f;
      f.kind = DeadlockKind::kIdleActive;
      f.description = "mission idle too long: " + m.id;
      f.mission_ids.push_back(m.id);
      findings.push_back(std::move(f));
    }
  }

  // 4. 启发式：长期持锁检测
  std::unordered_map<std::string, std::vector<std::string>> resource_to_missions;
  for (const auto& m : snapshot.active_missions) {
    if (!m.reservation_id.empty()) {
      resource_to_missions[m.reservation_id].push_back(m.id);
    }
  }
  for (const auto& [resource, acquired_at] : snapshot.reservation_acquired_at) {
    if (now - acquired_at <= config_.reservation_hold_threshold) {
      continue;
    }
    auto it = resource_to_missions.find(resource);
    if (it == resource_to_missions.end() || it->second.empty()) {
      continue;
    }
    DeadlockFinding f;
    f.kind = DeadlockKind::kLongReservationHold;
    f.description = "resource held too long: " + resource;
    f.mission_ids = it->second;
    findings.push_back(std::move(f));
  }

  return findings;
}

}  // namespace amr_dispatcher_core::dispatcher

